code.perFrame:
 // loudness (who would've thought THAT?) and bass loudness
loudness = loudness-(loudness-getspec(.4,.8,0))*.2;
loudbass = loudbass-(loudbass-getspec(.1,.25,0))*.5;
 // shrink render after beat
beat = beat*.6;
 // framerate independence
speed = (gettime(0)-t)*15; t = gettime(0); 
 // on-pause movement stop
pause = bnot(equal(gettime(-1),t2)); t2 = gettime(-1);
 // rotations
rx = rx+.483*loudness*speed*pause; ry = ry+.37647*loudness*speed*pause;
reg01 = sin(rx); reg02 = cos(rx);
reg03 = sin(ry); reg04 = cos(ry);
reg05 = sin(rz); reg06 = cos(rz);
 // linesize depending on screen size
linesize = (h+w)*.007;
 // aspect correction
asp = h/w;
 // draw lines
drawmode = 1;

code.onBeat:
 // make render .5 times bigger on beat
beat = .5;
 // the louder the bass, the higher the chance for a z-axis rotation position  change
rz = if(above(rand(100),(90-loudbass*200)),rand(200)*.01*$PI,rz)

code.perPoint:
r = i*100*$PI;
 // increase size on scope movement and beat
d = 1+v+beat;
 // it used to be sphere, hence this block of code...
x1 = sin(r)*cos((i*2-1)*$PI*.5)*d;
y1 = sin((i*2-1)*$PI*.5)+v*.02;
z1 = cos(r)*cos((i*2-1)*$PI*.5)*d;

x2 = x1*reg05-y1*reg06; y2 = x1*reg06+y1*reg05; z2 = x2*reg04+z1*reg03;
x3 = x2*reg03-z1*reg04; y3 = y2*reg01-z2*reg02; z3 = y2*reg02+z2*reg01;

iz = 4/(z3+8);
x = x3*iz*asp;
y = y3*iz;

blue=abs(x);
green=abs(y);
red=cos(dt*4)
